template <>
std::unique_ptr<vm_if> create<arch::rv64gcv>(arch::rv64gcv *core, unsigned short port, bool dump) {
    auto ret = new rv64gcv::vm_impl<arch::rv64gcv>(*core, dump);
    if (port != 0) debugger::server<debugger::gdb_session>::run_server(ret, port);
    return std::unique_ptr<vm_if>(ret);
}
